import { useEffect, useState } from "react";
import { type AboutInfo, commands } from "@/bindings";
import { Button } from "@/components/ui/button";
import { followSystemTheme } from "@/lib/theme";

export default function App() {
  const [about, setAbout] = useState<AboutInfo | null>(null);

  useEffect(() => followSystemTheme(), []);

  useEffect(() => {
    // Typed wrapper generated by tauri-specta. No hand-written invoke strings or types.
    void commands.getAboutInfo().then(setAbout);
  }, []);

  return (
    <main className="flex h-full flex-col items-center justify-center gap-4">
      <h1 className="text-3xl font-semibold tracking-tight">Frida</h1>
      <p className="text-muted-foreground">Fast Request Inspector for Developer APIs</p>
      {about && (
        <p className="text-sm text-muted-foreground" data-testid="about">
          {about.productName} core v{about.coreVersion}
        </p>
      )}
      <Button variant="outline" disabled>
        Open workspace…
      </Button>
    </main>
  );
}
